//! Task environment: synthetic, fully reproducible benchmark tasks.
//!
//! Three splits come from the same distribution with independent samples.
//! `Split::Hidden` must only be generated by the hidden evaluator,
//! from a seed the orchestrator never reads.

use std::f32::consts::{PI, TAU};

use rand::{Rng, SeedableRng};
use rand_chacha::ChaCha8Rng;
use serde::{Deserialize, Serialize};

use crate::util::{derive_seed, normal_f32};

/// Turns of each spiral arm in `TwoSpirals`.
pub const SPIRAL_TURNS: f32 = 3.0;

/// Bits in the `Parity` task.
pub const PARITY_BITS: usize = 8;

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum TaskKind {
    /// 2-D two-spirals, 2 classes (proposed by A. P. Wieland; Lang & Witbrock 1988).
    TwoSpirals,
    /// 2-D checkerboard on [-1, 1]^2, 4x4 cells, 2 classes. The label comes from the clean
    /// point; Gaussian input noise (std 0.02) is added afterwards, so about 5 % of the points
    /// lie in a cell of the other class and the best reachable accuracy is about 0.95.
    Checkerboard,
    /// 8-bit parity of inputs in {-1, +1}, 2 classes, with label noise 0.
    Parity,
    /// 1-D regression y = sin(3x) + 0.3 sin(9x) + noise on [-pi, pi].
    SineRegression,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum Split {
    Train,
    Valid,
    Hidden,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub enum Objective {
    /// Softmax cross-entropy; output size = classes.
    Classification { classes: usize },
    /// Mean squared error; output size = n_out.
    Regression,
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct TaskSpec {
    pub kind: TaskKind,
    pub n_in: usize,
    pub n_out: usize,
    pub objective: Objective,
    pub n_train: usize,
    pub n_valid: usize,
    pub n_hidden: usize,
    /// Input noise std (spirals, checkerboard) or target noise std (sine).
    pub noise: f32,
}

#[derive(Clone, Debug, PartialEq)]
pub enum Targets {
    /// Class index per sample.
    Labels(Vec<u32>),
    /// Row-major n x n_out values.
    Values(Vec<f32>),
}

#[derive(Clone, Debug, PartialEq)]
pub struct Dataset {
    /// Row-major n x n_in inputs.
    pub x: Vec<f32>,
    pub targets: Targets,
    pub n: usize,
    pub n_in: usize,
    pub n_out: usize,
}

impl TaskKind {
    /// Fixed spec for each task (sizes, objective, noise).
    pub fn spec(self) -> TaskSpec {
        match self {
            TaskKind::TwoSpirals => TaskSpec {
                kind: self,
                n_in: 2,
                n_out: 2,
                objective: Objective::Classification { classes: 2 },
                n_train: 400,
                n_valid: 400,
                n_hidden: 4000,
                noise: 0.03,
            },
            TaskKind::Checkerboard => TaskSpec {
                kind: self,
                n_in: 2,
                n_out: 2,
                objective: Objective::Classification { classes: 2 },
                n_train: 1000,
                n_valid: 1000,
                n_hidden: 4000,
                noise: 0.02,
            },
            TaskKind::Parity => TaskSpec {
                kind: self,
                n_in: PARITY_BITS,
                n_out: 2,
                objective: Objective::Classification { classes: 2 },
                n_train: 256,
                n_valid: 256,
                n_hidden: 1024,
                noise: 0.0,
            },
            TaskKind::SineRegression => TaskSpec {
                kind: self,
                n_in: 1,
                n_out: 1,
                objective: Objective::Regression,
                n_train: 500,
                n_valid: 500,
                n_hidden: 2000,
                noise: 0.1,
            },
        }
    }

    /// Parse a CLI name such as "spirals", "checkerboard", "parity", "sine".
    pub fn from_name(name: &str) -> Option<TaskKind> {
        let lower = name.trim().to_ascii_lowercase();

        match lower.as_str() {
            "spirals" | "twospirals" | "two-spirals" => Some(TaskKind::TwoSpirals),
            "checkerboard" => Some(TaskKind::Checkerboard),
            "parity" => Some(TaskKind::Parity),
            "sine" | "sineregression" | "sine-regression" => Some(TaskKind::SineRegression),
            _ => None,
        }
    }

    /// Short CLI name, the inverse of `from_name`.
    pub fn name(self) -> &'static str {
        match self {
            TaskKind::TwoSpirals => "spirals",
            TaskKind::Checkerboard => "checkerboard",
            TaskKind::Parity => "parity",
            TaskKind::SineRegression => "sine",
        }
    }
}

impl Split {
    /// Tag mixed into the seed of this split.
    fn tag(self) -> &'static str {
        match self {
            Split::Train => "split/train",
            Split::Valid => "split/valid",
            Split::Hidden => "split/hidden",
        }
    }
}

/// Generate one split. Deterministic in (spec, split, seed).
/// The split tag is mixed into the seed, so splits never share samples by seed reuse.
pub fn generate(spec: &TaskSpec, split: Split, seed: u64) -> Dataset {
    let n = match split {
        Split::Train => spec.n_train,
        Split::Valid => spec.n_valid,
        Split::Hidden => spec.n_hidden,
    };

    let mut rng = ChaCha8Rng::seed_from_u64(derive_seed(seed, split.tag()));
    let noise = if spec.noise.is_finite() {
        spec.noise.max(0.0)
    } else {
        0.0
    };

    match spec.kind {
        TaskKind::TwoSpirals => spirals(n, noise, &mut rng),
        TaskKind::Checkerboard => checkerboard(n, noise, &mut rng),
        TaskKind::Parity => parity(n, &mut rng),
        TaskKind::SineRegression => sine(n, noise, &mut rng),
    }
}

/// Two interleaved spiral arms, classes alternate, radius in [0, 1].
fn spirals(n: usize, noise: f32, rng: &mut ChaCha8Rng) -> Dataset {
    let mut x = Vec::with_capacity(n * 2);
    let mut labels = Vec::with_capacity(n);

    for i in 0..n {
        let class = (i % 2) as u32;
        let u: f32 = rng.random();

        // sqrt spreads the points evenly along the arm length.
        let t = u.sqrt();
        let angle = t * SPIRAL_TURNS * TAU + class as f32 * PI;
        let radius = t;

        let px = radius * angle.cos() + noise * normal_f32(rng);
        let py = radius * angle.sin() + noise * normal_f32(rng);

        x.push(px);
        x.push(py);
        labels.push(class);
    }

    Dataset {
        x,
        targets: Targets::Labels(labels),
        n,
        n_in: 2,
        n_out: 2,
    }
}

/// 4x4 checkerboard on [-1, 1]^2. Label from the clean point, then input noise.
fn checkerboard(n: usize, noise: f32, rng: &mut ChaCha8Rng) -> Dataset {
    let mut x = Vec::with_capacity(n * 2);
    let mut labels = Vec::with_capacity(n);

    for _ in 0..n {
        let px: f32 = rng.random_range(-1.0..1.0);
        let py: f32 = rng.random_range(-1.0..1.0);

        let cx = (((px + 1.0) * 2.0).floor() as i64).clamp(0, 3);
        let cy = (((py + 1.0) * 2.0).floor() as i64).clamp(0, 3);
        let class = ((cx + cy) % 2) as u32;

        x.push(px + noise * normal_f32(rng));
        x.push(py + noise * normal_f32(rng));
        labels.push(class);
    }

    Dataset {
        x,
        targets: Targets::Labels(labels),
        n,
        n_in: 2,
        n_out: 2,
    }
}

/// Parity of `PARITY_BITS` inputs in {-1, +1}. No label noise.
fn parity(n: usize, rng: &mut ChaCha8Rng) -> Dataset {
    let mut x = Vec::with_capacity(n * PARITY_BITS);
    let mut labels = Vec::with_capacity(n);

    for _ in 0..n {
        let mut ones = 0u32;

        for _ in 0..PARITY_BITS {
            let bit = rng.random_bool(0.5);

            if bit {
                ones += 1;
            }

            x.push(if bit { 1.0 } else { -1.0 });
        }

        labels.push(ones % 2);
    }

    Dataset {
        x,
        targets: Targets::Labels(labels),
        n,
        n_in: PARITY_BITS,
        n_out: 2,
    }
}

/// y = sin(3x) + 0.3 sin(9x) + noise, x uniform on [-pi, pi].
fn sine(n: usize, noise: f32, rng: &mut ChaCha8Rng) -> Dataset {
    let mut x = Vec::with_capacity(n);
    let mut values = Vec::with_capacity(n);

    for _ in 0..n {
        let px: f32 = rng.random_range(-PI..PI);
        let clean = (3.0 * px).sin() + 0.3 * (9.0 * px).sin();

        x.push(px);
        values.push(clean + noise * normal_f32(rng));
    }

    Dataset {
        x,
        targets: Targets::Values(values),
        n,
        n_in: 1,
        n_out: 1,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const ALL: [TaskKind; 4] = [
        TaskKind::TwoSpirals,
        TaskKind::Checkerboard,
        TaskKind::Parity,
        TaskKind::SineRegression,
    ];

    #[test]
    fn spec_sizes_match_generated_data() {
        for kind in ALL {
            let spec = kind.spec();

            for split in [Split::Train, Split::Valid, Split::Hidden] {
                let data = generate(&spec, split, 11);
                let n = match split {
                    Split::Train => spec.n_train,
                    Split::Valid => spec.n_valid,
                    Split::Hidden => spec.n_hidden,
                };

                assert_eq!(data.n, n);
                assert_eq!(data.n_in, spec.n_in);
                assert_eq!(data.n_out, spec.n_out);
                assert_eq!(data.x.len(), n * spec.n_in);
                assert!(data.x.iter().all(|v| v.is_finite()));

                match (&data.targets, spec.objective) {
                    (Targets::Labels(l), Objective::Classification { classes }) => {
                        assert_eq!(l.len(), n);
                        assert!(l.iter().all(|&c| (c as usize) < classes));
                    }
                    (Targets::Values(v), Objective::Regression) => {
                        assert_eq!(v.len(), n * spec.n_out);
                        assert!(v.iter().all(|y| y.is_finite()));
                    }
                    _ => panic!("targets do not match objective for {kind:?}"),
                }
            }
        }
    }

    #[test]
    fn generation_is_deterministic() {
        for kind in ALL {
            let spec = kind.spec();

            assert_eq!(
                generate(&spec, Split::Train, 5),
                generate(&spec, Split::Train, 5)
            );
        }
    }

    #[test]
    fn splits_and_seeds_differ() {
        let spec = TaskKind::TwoSpirals.spec();
        let train = generate(&spec, Split::Train, 5);
        let valid = generate(&spec, Split::Valid, 5);
        let other = generate(&spec, Split::Train, 6);

        assert_ne!(train.x[..20], valid.x[..20]);
        assert_ne!(train.x[..20], other.x[..20]);
    }

    #[test]
    fn classes_are_balanced_enough() {
        for kind in [
            TaskKind::TwoSpirals,
            TaskKind::Checkerboard,
            TaskKind::Parity,
        ] {
            let data = generate(&kind.spec(), Split::Train, 1);
            let Targets::Labels(labels) = &data.targets else {
                panic!("expected labels");
            };
            let ones = labels.iter().filter(|&&c| c == 1).count() as f64 / labels.len() as f64;

            assert!((0.4..0.6).contains(&ones), "{kind:?}: {ones}");
        }
    }

    #[test]
    fn parity_labels_are_correct() {
        let data = generate(&TaskKind::Parity.spec(), Split::Valid, 2);
        let Targets::Labels(labels) = &data.targets else {
            panic!("expected labels");
        };

        for (row, &label) in data.x.chunks_exact(PARITY_BITS).zip(labels) {
            let ones = row.iter().filter(|&&v| v > 0.0).count() as u32;

            assert_eq!(ones % 2, label);
        }
    }

    #[test]
    fn names_round_trip() {
        for kind in ALL {
            assert_eq!(TaskKind::from_name(kind.name()), Some(kind));
        }

        assert_eq!(TaskKind::from_name("Spirals"), Some(TaskKind::TwoSpirals));
        assert_eq!(TaskKind::from_name("nope"), None);
    }
}
